#[test]
fn ed25519_matches_reference() {
    for (seed, pk, msg, sig) in ED25519 {
        let seed: [u8; 32] = unhex(seed).try_into().unwrap();
        let pk: [u8; 32] = unhex(pk).try_into().unwrap();
        let msg = unhex(msg);
        let sig: [u8; 64] = unhex(sig).try_into().unwrap();
        assert_eq!(public_key_from_seed(&seed), pk, "clave pública");
        assert_eq!(sign(&seed, &msg), sig, "firma (len {})", msg.len());
        assert!(verify(&pk, &msg, &sig), "verificación (len {})", msg.len());
        // la firma de referencia no vale para otro mensaje
        let mut other = msg.clone();
        other.push(1);
        assert!(!verify(&pk, &other, &sig));
    }
}

#[test]
fn sha512_hmac_match_reference() {
    for (key, data, mac, digest) in HMAC {
        let (key, data) = (unhex(key), unhex(data));
        assert_eq!(hex(&hmac_sha512(&key, &data)), mac, "hmac key {} data {}", key.len(), data.len());
        assert_eq!(hex(&sha512(&data)), digest);
    }
}

#[test]
fn pbkdf2_matches_reference() {
    for (pw, salt, c, dk, expected) in PBKDF2 {
        let mut out = vec![0u8; dk];
        pbkdf2_hmac_sha512(&unhex(pw), &unhex(salt), c, &mut out);
        assert_eq!(hex(&out), expected, "c={c} dk={dk}");
    }
}

#[test]
fn slip10_matches_reference() {
    for (seed, path, key, chain, pk) in SLIP10 {
        let path: Vec<u32> =
            if path.is_empty() { vec![] } else { path.split(',').map(|p| p.parse::<u32>().unwrap() | HARDENED).collect() };
        let k = ExtKey::master(&unhex(seed)).unwrap().derive_path(&path).unwrap();
        assert_eq!(hex(&k.private_key()), key);
        assert_eq!(hex(&k.chain_code()), chain);
        assert_eq!(hex(&k.keypair().public_key()), pk);
    }
}

#[test]
fn bip39_matches_reference() {
    for (ent, phrase, pwd, seed) in BIP39 {
        let m = Mnemonic::from_entropy(&unhex(ent)).unwrap();
        assert_eq!(m.phrase(), phrase);
        assert_eq!(hex(&m.to_seed(pwd)), seed);
        assert_eq!(hex(&Mnemonic::from_phrase(phrase).unwrap().to_entropy()), ent);
    }
}

#[test]
fn addresses_match_reference() {
    for (pk, addr, text) in ADDRESSES {
        let a = address_from_public_key(&unhex(pk).try_into().unwrap());
        assert_eq!(hex(&a.0), addr);
        assert_eq!(encode(&a), text);
        assert_eq!(decode(text), Ok(a));
    }
}
